11	// AddLayerNorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
12	// Supports: x_add = x1 + x2 (+ bias) → LayerNorm
13	
14	#include <algorithm>
15	#include <cstdint>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_add_layer_norm_merge_n.h"
24	#include "aclrtlaunch_add_layer_norm_single_row.h"
25	#include "aclrtlaunch_add_layer_norm_splitd.h"
26	
27	// ---------------------------------------------------------------------------
28	// Tiling constants
29	// ---------------------------------------------------------------------------
30	
31	constexpr int32_t DEFAULT_BLOCK_M = 64;
32	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
33	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
34	
35	// ---------------------------------------------------------------------------
36	// Host function
37	// ---------------------------------------------------------------------------
38	
39	namespace ascend_kernel {
40	
41	std::vector<at::Tensor> add_layer_norm(
42	    const at::Tensor &x1,
43	    const at::Tensor &x2,
44	    const at::Tensor &bias,
45	    const at::Tensor &gamma,
46	    const at::Tensor &beta,
47	    double eps,
48	    bool additionalOut)
49	{
50	    TORCH_CHECK(x1.dim() == 2, "x1 must be 2D [M, N]");
51	    TORCH_CHECK(x2.dim() == 2, "x2 must be 2D [M, N]");
52	    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
53	    TORCH_CHECK(beta.dim() == 1, "beta must be 1D [N]");
54	    TORCH_CHECK(
55	        x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
56	            x1.scalar_type() == at::kBFloat16,
57	        "x1 must be float16, float32, or bfloat16");
58	    TORCH_CHECK(x2.scalar_type() == x1.scalar_type(),
59	        "x2 must have the same dtype as x1");
60	    TORCH_CHECK(gamma.scalar_type() == x1.scalar_type(),
61	        "gamma must have the same dtype as x1");
62	    TORCH_CHECK(beta.scalar_type() == x1.scalar_type(),
63	        "beta must have the same dtype as x1");
64	    TORCH_CHECK(x1.is_contiguous(), "x1 must be contiguous");
65	    TORCH_CHECK(x2.is_contiguous(), "x2 must be contiguous");
66	    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
67	    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");
68	
69	    int32_t M = static_cast<int32_t>(x1.sizes()[0]);
70	    int32_t N = static_cast<int32_t>(x1.sizes()[1]);
71	
72	    // Process bias: determine biasFlag and bias tensor
73	    // biasFlag: -1 = no bias, 0 = broadcast from [N], 1 = per-row from [M, N]
74	    at::Tensor biasInput;
75	    int64_t biasFlag = -1;
76	    if (bias.defined()) {
77	        auto biasSizes = bias.sizes();
78	        if (biasSizes.size() == 1 && biasSizes[0] == static_cast<int64_t>(N)) {
79	            biasInput = bias.contiguous();
80	            biasFlag = 0;
81	            TORCH_CHECK(biasInput.scalar_type() == x1.scalar_type(),
82	                "bias must have the same dtype as x1");
83	        } else if (static_cast<int64_t>(biasSizes.size()) == 2 &&
84	                   biasSizes[0] == static_cast<int64_t>(M) &&
85	                   biasSizes[1] == static_cast<int64_t>(N)) {
86	            biasInput = bias.contiguous();
87	            biasFlag = 1;
88	            TORCH_CHECK(biasInput.scalar_type() == x1.scalar_type(),
89	                "bias must have the same dtype as x1");
90	        } else {
91	            TORCH_CHECK(false, "bias shape must be [N] or [M, N]");
92	        }
93	    } else {
94	        // Create dummy 1D bias for kernel
95	        biasInput = at::zeros({N}, x1.options());
96	        biasFlag = -1;
97	    }
98	
99	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
100	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
101	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
102	
103	    // Output tensors
104	    at::Tensor y = at::empty_like(x1);
105	    at::Tensor xAddOut = at::empty_like(x1);
106	
107	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
108	    int64_t dtypeFlag = 0;
109	    if (x1.scalar_type() == at::kHalf) {
110	        dtypeFlag = 1;
111	    } else if (x1.scalar_type() == at::kBFloat16) {
112	        dtypeFlag = 2;
113	    }
114	
115	    int64_t additionalOutFlag = additionalOut ? 1 : 0;
116	
117	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
118	    int32_t blockM = DEFAULT_BLOCK_M;
119	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
120	    float epsVal = static_cast<float>(eps);
121	    float invN = 1.0f / static_cast<float>(N);
122	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
123	
124	    // Strategy dispatch: select kernel name and params
125	    if (N <= 1024) {
126	        EXEC_KERNEL_CMD(add_layer_norm_merge_n, blockDim,
127	                        x1, x2, biasInput, gamma, beta, y, xAddOut,
128	                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor,
129	                        epsVal, invN, biasFlag, additionalOutFlag, dtypeFlag);
130	    } else if (N > 8192) {
131	        EXEC_KERNEL_CMD(add_layer_norm_splitd, blockDim,
132	                        x1, x2, biasInput, gamma, beta, y, xAddOut,
133	                        M, N, blockM, usedCoreNum, tasksPerCore,
134	                        epsVal, invN, biasFlag, additionalOutFlag, dtypeFlag);
135	    } else {
136	        EXEC_KERNEL_CMD(add_layer_norm_single_row, blockDim,
137	                        x1, x2, biasInput, gamma, beta, y, xAddOut,
138	                        M, N, blockM, usedCoreNum, tasksPerCore,
139	                        epsVal, invN, biasFlag, additionalOutFlag, dtypeFlag);
140	    }
141	
142	    return {y, xAddOut};
143	}
144	
145	}  // namespace ascend_kernel
