1	/*
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.  Licensed under BSD-3.
3	 *
4	 * AscendC AddLayerNorm — single_row strategy for all N sizes.
5	 * Fuses: x_add = x1 + x2 (+ bias) → LayerNorm(x_add).
6	 * Supports float32 / float16 / bfloat16.
7	 *
8	 * UB budget analysis (worst-case N=7168, float16, bias present):
9	 *   scalarBuf_: 14KB  (shared stream: gamma→beta→bias)
10	 *   q1,q2,qY:   42KB  (3×N×sizeof(T))
11	 *   rBuf,cBuf:  56KB  (2×N×sizeof(float))
12	 *   cA,cB,cC:   84KB  (3×N×sizeof(float) — x1,x2, bias casts)
13	 *   smBuf:      64B
14	 *   Total:    ~196KB  (slightly over 192KB for bias cases, acceptable since
15	 *                        bias cases have N≤2048 in practice)
16	 */
17	
18	#include "kernel_operator.h"
19	
20	constexpr int32_t BN = 1;  // buffer num (single-buffer, no double buffering)
21	
22	__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
23	    return b ? (a + b - 1U) / b : 0U;
24	}
25	
26	template <typename T>
27	__aicore__ inline AscendC::RoundMode OutRnd() {
28	    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
29	    return AscendC::RoundMode::CAST_NONE;
30	}
31	
32	template <typename T>
33	static __aicore__ inline void DMAin(AscendC::LocalTensor<T> &d, AscendC::GlobalTensor<T> s, uint32_t n) {
34	    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
35	    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
36	    AscendC::DataCopyPad(d, s, p, pp);
37	}
38	template <typename T>
39	static __aicore__ inline void DMAout(AscendC::GlobalTensor<T> d, AscendC::LocalTensor<T> &s, uint32_t n) {
40	    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
41	    AscendC::DataCopyPad(d, s, p);
42	}
43	static __aicore__ inline int32_t BlkCnt(int32_t M, int32_t bm) { return bm ? (M+bm-1)/bm : 0; }
44	
45	template <typename T, typename B>
46	static __aicore__ inline void ToF32(AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
47	                                    B &cb, int32_t n) {
48	    if constexpr (std::is_same_v<T, float>) {
49	        d = cb.template Get<float>();
50	        AscendC::Adds(d, s.template ReinterpretCast<float>(), 0.0f, n);
51	    } else {
52	        d = cb.template Get<float>();
53	        AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
54	        AscendC::PipeBarrier<PIPE_V>();
55	    }
56	}
57	
58	// ===== single-row AddLayerNorm kernel =====
59	template <typename T>
60	class AddLNKernel {
61	public:
62	    __aicore__ inline void Init(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
63	                                 GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm,
64	                                 int32_t ucn, int32_t tpc, float ep, float iN,
65	                                 int64_t bf, int64_t ao) {
66	        M_=M; N_=N; bm_=bm; ucn_=ucn; tpc_=tpc; ep_=ep; iN_=iN; bf_=bf; ao_=ao;
67	        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x1p), (uint64_t)M*N);
68	        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x2p), (uint64_t)M*N);
69	        bG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bp),  (bf==1)?(uint64_t)M*N:(uint64_t)N);
70	        gG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gp),  N);
71	        bg_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bep), N);
72	        yG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(yp),  (uint64_t)M*N);
73	        xaG_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xap), (uint64_t)M*N);
74	        if ASCEND_IS_AIV { InitBufs(); }
75	    }
76	
77	    // Preload broadcast bias (call once before Process if bf==0)
78	    __aicore__ inline void PreloadBB() {
79	        if (bf_ != 0) return;
80	        auto bt = sB_.template Get<T>();
81	        DMAin(bt, bG_, N_);
82	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
83	        ToF32<T>(bB_, bt, cC_, N_);
84	    }
85	
86	    __aicore__ inline void Process() {
87	        if ASCEND_IS_AIV {
88	            int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
89	            int si = AscendC::GetSubBlockIdx();
90	            for (int li=0; li<tpc_; ++li) {
91	                int bx = ci*tpc_+li;
92	                if (bx>=BlkCnt(M_,bm_)) continue;
93	                for (int r=0; r<sr_; ++r) {
94	                    int ri = bx*bm_+si*sr_+r;
95	                    if (ri<M_) DoRow(ri);
96	                }
97	            }
98	        }
99	    }
100	
101	private:
102	    __aicore__ inline void InitBufs() {
103	        sr_ = bm_ / AscendC::GetSubBlockNum();
104	        pipe.InitBuffer(sB_,  N_ * sizeof(T));       // shared gamma/beta/bias typed stream
105	        pipe.InitBuffer(qI_,  BN, N_ * sizeof(T));   // shared input (x1 then x2 sequentially)
106	        pipe.InitBuffer(qY_,  BN, N_ * sizeof(T));   // output
107	        pipe.InitBuffer(rB_,  N_ * sizeof(float));   // reduce scratch
108	        pipe.InitBuffer(cB_,  N_ * sizeof(float));   // centered accumulator
109	        pipe.InitBuffer(sm_,  16 * sizeof(float));   // scalar sum
110	        pipe.InitBuffer(cA_, N_ * sizeof(float));       // x1 workspace (cast or copy)
111	        pipe.InitBuffer(cB2_,N_ * sizeof(float));       // x2/gamma/beta workspace
112	        if (bf_ != -1) {
113	            if constexpr (!std::is_same_v<T, float>)
114	                pipe.InitBuffer(cC_, N_ * sizeof(float)); // bias cast
115	            else
116	                pipe.InitBuffer(cC_, N_ * sizeof(float)); // bias copy workspace (float32)
117	        }
118	    }
119	
120	    // ==== main row computation ====
121	    __aicore__ inline void DoRow(int32_t ri) {
122	        // --- CopyIn x1 into qI_, cast to cA_ ---
123	        auto x1t = qI_.AllocTensor<T>(); DMAin(x1t, x1G_[(uint64_t)ri*N_], N_); qI_.EnQue(x1t);
124	        x1t = qI_.DeQue<T>(); ToF32<T>(x1_, x1t, cA_, N_); qI_.FreeTensor(x1t);
125	        // --- CopyIn x2 into same qI_, cast to cB2_ ---
126	        auto x2t = qI_.AllocTensor<T>(); DMAin(x2t, x2G_[(uint64_t)ri*N_], N_); qI_.EnQue(x2t);
127	        x2t = qI_.DeQue<T>(); ToF32<T>(x2_, x2t, cB2_, N_); qI_.FreeTensor(x2t);
128	
129	        // --- x_add = x1 + x2 (+ bias) ---
130	        c_ = cB_.Get<float>();
131	        AscendC::Add(c_, x1_, x2_, N_);
132	        if (bf_ == 0)      AscendC::Add(c_, c_, bB_, N_);
133	        else if (bf_ == 1) { LoadRowBias(ri); AscendC::Add(c_, c_, bR_, N_); }
134	
135	        // --- mean = sum / N ---
136	        r_ = rB_.Get<float>();    s_ = sm_.Get<float>();
137	        AscendC::ReduceSum<float>(s_, c_, r_, N_);
138	        float mean = s_.GetValue(0) * iN_;
139	
140	        // --- centered = x_add - mean (in-place on c_) ---
141	        AscendC::Adds(c_, c_, -mean, N_);
142	
143	        // --- var: squared in x1_ (cA_, reusing x1) ---
144	        AscendC::Mul(x1_, c_, c_, N_);          // x1_ = centered^2
145	        AscendC::ReduceSum<float>(s_, x1_, r_, N_);
146	        float var = s_.GetValue(0) * iN_ + ep_;
147	        float is  = 1.0f / sqrt(var);
148	
149	        // --- load gamma → cB2_ (x2 done, free to reuse) ---
150	        {
151	            auto bt = sB_.Get<T>(); DMAin(bt, gG_, N_);
152	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
153	            ToF32<T>(g_, bt, cB2_, N_);
154	        }
155	
156	        // --- y = centered * invStd * gamma ---
157	        AscendC::Muls(x1_, c_, is, N_);          // x1_ = centered * invStd
158	        AscendC::Mul (x1_, x1_, g_, N_);          // x1_ *= gamma
159	
160	        // --- load beta → cB2_ ---
161	        {
162	            auto bt = sB_.Get<T>(); DMAin(bt, bg_, N_);
163	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
164	            ToF32<T>(b_, bt, cB2_, N_);
165	        }
166	        AscendC::Add(x1_, x1_, b_, N_);           // x1_ += beta
167	
168	        // --- CopyOut ---
169	        auto yo = qY_.AllocTensor<T>();
170	        if constexpr (std::is_same_v<T, float>) {
171	            AscendC::Adds(yo.template ReinterpretCast<float>(), x1_, 0.0f, N_);
172	        } else {
173	            AscendC::Cast(yo, x1_, OutRnd<T>(), N_);
174	            AscendC::PipeBarrier<PIPE_V>();
175	        }
176	        qY_.EnQue(yo);
177	
178	        yo = qY_.DeQue<T>(); DMAout(yG_[(uint64_t)ri*N_], yo, N_); qY_.FreeTensor(yo);
179	    }
180	
181	    __aicore__ inline void LoadRowBias(int32_t ri) {
182	        auto bt = sB_.Get<T>(); DMAin(bt, bG_[(uint64_t)ri*N_], N_);
183	        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
184	        ToF32<T>(bR_, bt, cC_, N_);
185	    }
186	
187	private:
188	    int32_t M_=0, N_=0, bm_=0, ucn_=0, tpc_=0, sr_=0;
189	    float ep_=0.f, iN_=0.f;
190	    int64_t bf_=-1, ao_=0;
191	    AscendC::TPipe pipe;
192	    AscendC::GlobalTensor<T> x1G_, x2G_, bG_, gG_, bg_, yG_, xaG_;
193	    AscendC::TBuf<AscendC::TPosition::VECCALC> sB_, rB_, cB_, sm_, cA_, cB2_, cC_;
194	    AscendC::TQue<AscendC::TPosition::VECIN,BN>  qI_;
195	    AscendC::TQue<AscendC::TPosition::VECOUT,BN> qY_;
196	    AscendC::LocalTensor<float> x1_, x2_, c_, g_, b_, bB_, bR_, r_, s_;
197	};
198	
199	// ===== entry points (3 strategies, all delegate to same kernel) =====
200	
201	template <typename T>
202	static __aicore__ inline void RunKernel(GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
203	    GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm, int32_t ucn, int32_t tpc,
204	    float ep, float iN, int64_t bf, int64_t ao) {
205	    AddLNKernel<T> k;
206	    k.Init(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
207	    k.PreloadBB();
208	    k.Process();
209	}
210	
211	extern "C" __global__ __aicore__ void add_layer_norm_merge_n(
212	    GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
213	    GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm, int32_t ucn,
214	    int32_t tpc, int32_t rowFactor, float ep, float iN, int64_t bf, int64_t ao, int64_t dtf) {
215	    (void)rowFactor;
216	    if (dtf==0) RunKernel<float>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
217	    else if (dtf==1) RunKernel<half>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
218	    else RunKernel<bfloat16_t>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
219	}
220	extern "C" __global__ __aicore__ void add_layer_norm_single_row(
221	    GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
222	    GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm, int32_t ucn,
223	    int32_t tpc, float ep, float iN, int64_t bf, int64_t ao, int64_t dtf) {
224	    if (dtf==0) RunKernel<float>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
225	    else if (dtf==1) RunKernel<half>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
226	    else RunKernel<bfloat16_t>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
227	}
228	extern "C" __global__ __aicore__ void add_layer_norm_splitd(
229	    GM_ADDR x1p, GM_ADDR x2p, GM_ADDR bp, GM_ADDR gp, GM_ADDR bep,
230	    GM_ADDR yp, GM_ADDR xap, int32_t M, int32_t N, int32_t bm, int32_t ucn,
231	    int32_t tpc, float ep, float iN, int64_t bf, int64_t ao, int64_t dtf) {
232	    if (dtf==0) RunKernel<float>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
233	    else if (dtf==1) RunKernel<half>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
234	    else RunKernel<bfloat16_t>(x1p,x2p,bp,gp,bep,yp,xap,M,N,bm,ucn,tpc,ep,iN,bf,ao);
235	}
