        pipe.InitBuffer(qX_,  BN, N_ * sizeof(T));   // input x
        pipe.InitBuffer(qGX_, BN, N_ * sizeof(T));   // input gx
        pipe.InitBuffer(qY_,  BN, N_ * sizeof(T));   // output y
