// DeepNorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
// Computation: x_add = x * alpha + gx → DeepNorm(x_add)
// Outputs: mean[M, 1], rstd[M, 1], y_out[M, N]

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_deep_norm_merge_n.h"
#include "aclrtlaunch_deep_norm_single_row.h"
#include "aclrtlaunch_deep_norm_splitd.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_ROW_FACTOR = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::vector<at::Tensor> deep_norm(
    const at::Tensor &x,
    const at::Tensor &gx,
    const at::Tensor &gamma,
    const at::Tensor &beta,
    double alpha,
    double epsilon)
{
    TORCH_CHECK(x.dim() >= 2, "x must be at least 2D");
    TORCH_CHECK(gx.dim() >= 2, "gx must be at least 2D");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
    TORCH_CHECK(beta.dim() == 1, "beta must be 1D [N]");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float16, float32, or bfloat16");
    TORCH_CHECK(gx.scalar_type() == x.scalar_type(),
        "gx must have the same dtype as x");
    TORCH_CHECK(gamma.scalar_type() == x.scalar_type(),
        "gamma must have the same dtype as x");
    TORCH_CHECK(beta.scalar_type() == x.scalar_type(),
        "beta must have the same dtype as x");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(gx.is_contiguous(), "gx must be contiguous");
    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");

    // Flatten to 2D: [..., N] → [M, N]
    at::Tensor x2d = x.reshape({-1, x.size(-1)}).contiguous();
    at::Tensor gx2d = gx.reshape({-1, gx.size(-1)}).contiguous();
    at::Tensor gamma1d = gamma.reshape({-1}).contiguous();
    at::Tensor beta1d = beta.reshape({-1}).contiguous();

    int32_t M = static_cast<int32_t>(x2d.sizes()[0]);
    int32_t N = static_cast<int32_t>(x2d.sizes()[1]);

    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // Output tensors: mean [M, 1], rstd [M, 1], y_out [M, N]
    at::Tensor meanOut = at::empty({M, 1}, x2d.options());
    at::Tensor rstdOut = at::empty({M, 1}, x2d.options());
    at::Tensor yOut = at::empty_like(x2d);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x2d.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x2d.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t rowFactor = DEFAULT_ROW_FACTOR;
    float alphaVal = static_cast<float>(alpha);
    float epsVal = static_cast<float>(epsilon);
    float invN = 1.0f / static_cast<float>(N);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Strategy dispatch: select kernel name and params
    if (N <= 1024) {
        EXEC_KERNEL_CMD(deep_norm_merge_n, blockDim,
                        x2d, gx2d, gamma1d, beta1d, meanOut, rstdOut, yOut,
                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor,
                        alphaVal, epsVal, invN, dtypeFlag);
    } else if (N > 8192) {
        EXEC_KERNEL_CMD(deep_norm_splitd, blockDim,
                        x2d, gx2d, gamma1d, beta1d, meanOut, rstdOut, yOut,
                        M, N, blockM, usedCoreNum, tasksPerCore,
                        alphaVal, epsVal, invN, dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(deep_norm_single_row, blockDim,
                        x2d, gx2d, gamma1d, beta1d, meanOut, rstdOut, yOut,
                        M, N, blockM, usedCoreNum, tasksPerCore,
                        alphaVal, epsVal, invN, dtypeFlag);
    }

    return {meanOut, rstdOut, yOut};
}

}  // namespace ascend_kernel
