{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.  Licensed under BSD-3.
 *
 * AscendC DeepNorm — single_row strategy for all N sizes.
 * Fuses: x_add = x * alpha + gx → DeepNorm(x_add).
 * Supports float32 / float16 / bfloat16.
 *
 * Computation per row (all in float32 internally):
 *   1. x_add = x * alpha + gx
 *   2. mean = reduce_sum(x_add) / N
 *   3. diff = x_add - mean
 *   4. variance = reduce_sum(diff^2) / N + eps
 *   5. rstd = 1 / sqrt(variance)
 *   6. y_out = gamma * diff * rstd + beta
 *
 * Outputs: mean[M, 1], rstd[M, 1], y_out[M, N]
 *
 * UB budget (worst-case N=2048, float16):
 *   sB_:        4KB  (shared gamma/beta input)
 *   qX,qGX,qY: 12KB  (3 × N × sizeof(T))
 *   rB_:        8KB  (reduce scratch)
 *   sm_:       64B   (scalar sum)
 *   cA_:        8KB  (x cast)
 *   cB_:        8KB  (main compute: gx cast → diff^2 → gamma → beta)
 *   cD_:       32B   (scalar out buffer)
 *   Total:    ~40KB (well under 192KB UB)
 */

#include "kernel_operator.h"

constexpr int32_t BN = 1;  // buffer num (single-buffer)

__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
    return b ? (a + b - 1U) / b : 0U;
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutRnd() {
    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
static __aicore__ inline void DMAin(AscendC::LocalTensor<T> &d, AscendC::GlobalTensor<T> s, uint32_t n) {
    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(d, s, p, pp);
}
template <typename T>
static __aicore__ inline void DMAout(AscendC::GlobalTensor<T> d, AscendC::LocalTensor<T> &s, uint32_t n) {
    AscendC::DataCopyExtParams p{1, n * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(d, s, p);
}
static __aicore__ inline int32_t BlkCnt(int32_t M, int32_t bm) { return bm ? (M+bm-1)/bm : 0; }

template <typename T, typename B>
static __aicore__ inline void ToF32(AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
                                    B &cb, int32_t n) {
    if constexpr (std::is_same_v<T, float>) {
        d = cb.template Get<float>();
        AscendC::Adds(d, s.template ReinterpretCast<float>(), 0.0f, n);
    } else {
        d = cb.template Get<float>();
        AscendC::Cast(d, s, AscendC::RoundMode::CAST_NONE, n);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// Helper: write one scalar value to GM using TBuf + DataCopyPad
template <typename T>
static __aicore__ inline void WriteOne(AscendC::GlobalTensor<T> gDst, float val,
                                        AscendC::TPipe &pipe,
                                        AscendC::TBuf<AscendC::TPosition::VECCALC> &tmpBuf) {
    auto t = tmpBuf.template Get<T>();
    if constexpr (std::is_same_v<T, float>) {
        t.SetValue(0, val);
    } else {
        auto tf = t.template ReinterpretCast<float>();
        tf.SetValue(0, val);
        AscendC::Cast(t, tf, OutRnd<T>(), 1);
        AscendC::PipeBarrier<PIPE_V>();
    }
    AscendC::DataCopyExtParams p{1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(gDst, t, p);
    AscendC::PipeBarrier<PIPE_MTE2>();
}

// ===== single-row DeepNorm kernel =====
template <typename T>
class DeepNormKernel {
public:
    __aicore__ inline void Init(GM_ADDR xp, GM_ADDR gxp, GM_ADDR gp, GM_ADDR bep,
                                 GM_ADDR mp, GM_ADDR rp, GM_ADDR yp,
                                 int32_t M, int32_t N, int32_t bm,
                                 int32_t ucn, int32_t tpc, float alp, float ep, float iN) {
        M_=M; N_=N; bm_=bm; ucn_=ucn; tpc_=tpc; alp_=alp; ep_=ep; iN_=iN;
        xG_  .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xp),  (uint64_t)M*N);
        gxG_ .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gxp), (uint64_t)M*N);
        gG_  .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gp),  N);
        bg_  .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bep), N);
        mG_  .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(mp),  M);
        rG_  .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(rp),  M);
        yG_  .SetGlobalBuffer(reinterpret_cast<__gm__ T*>(yp),  (uint64_t)M*N);
        if ASCEND_IS_AIV { InitBufs(); }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int si = AscendC::GetSubBlockIdx();
            for (int li=0; li<tpc_; ++li) {
                int bx = ci*tpc_+li;
                if (bx>=BlkCnt(M_,bm_)) continue;
                for (int r=0; r<sr_; ++r) {
                    int ri = bx*bm_+si*sr_+r;
                    if (ri<M_) DoRow(ri);
                }
            }
        }
    }

private:
    __aicore__ inline void InitBufs() {
        sr_ = bm_ / AscendC::GetSubBlockNum();
        pipe.InitBuffer(sB_,  N_ * sizeof(T));       // shared gamma/beta typed stream
        pipe.InitBuffer(qX_,  BN, N_ * sizeof(T));   // input x queue
        pipe.InitBuffer(qGX_, BN, N_ * sizeof(T));   // input gx queue
        pipe.InitBuffer(qY_,  BN, N_ * sizeof(T));   // output y queue
        pipe.InitBuffer(rB_,  N_ * sizeof(float));   // reduce scratch
        pipe.InitBuffer(sm_,  16 * sizeof(float));   // scalar sum
        pipe.InitBuffer(cA_,  N_ * sizeof(float));   // x cast buffer (x1-equivalent)
        pipe.InitBuffer(cB_,  N_ * sizeof(float));   // main compute buffer (gx → diff^2 → gamma → beta)
        pipe.InitBuffer(cD_,  16 * sizeof(T));       // small scalar output
    }

    __aicore__ inline void DoRow(int32_t ri) {
        // --- CopyIn x into qX_, cast to cA_ (x_) ---
        auto xt = qX_.AllocTensor<T>(); DMAin(xt, xG_[(uint64_t)ri*N_], N_); qX_.EnQue(xt);
        xt = qX_.DeQue<T>(); ToF32<T>(x_, xt, cA_, N_); qX_.FreeTensor(xt);
        // --- CopyIn gx into qGX_, cast to cB_ (gx_) ---
        auto gxt = qGX_.AllocTensor<T>(); DMAin(gxt, gxG_[(uint64_t)ri*N_], N_); qGX_.EnQue(gxt);
        gxt = qGX_.DeQue<T>(); ToF32<T>(gx_, gxt, cB_, N_); qGX_.FreeTensor(gxt);

        // --- x_add = x * alpha + gx (in c_ from cB_, reusing gx area) ---
        c_ = cB_.Get<float>();
        AscendC::Muls(c_, x_, alp_, N_);
        AscendC::Add(c_, c_, gx_, N_);

        // --- mean = sum(x_add) / N ---
        r_ = rB_.Get<float>();    s_ = sm_.Get<float>();
        AscendC::ReduceSum<float>(s_, c_, r_, N_);
        float meanVal = s_.GetValue(0) * iN_;

        // --- centered = x_add - mean (in-place on c_) ---
        AscendC::Adds(c_, c_, -meanVal, N_);

        // --- diff^2 in cA_ (reusing x_ buffer, no longer needed) ---
        AscendC::Mul(x_, c_, c_, N_);         // x_ = diff^2
        AscendC::ReduceSum<float>(s_, x_, r_, N_);
        float varVal = s_.GetValue(0) * iN_ + ep_;
        float rstdVal = 1.0f / sqrt(varVal);

        // --- y = diff * rstd → write to x_ (cA_, different from c_) ---
        AscendC::Muls(x_, c_, rstdVal, N_);   // x_ = diff * rstd

        // --- load gamma → cB_ (gama_, reusing cB_ area) ---
        {
            auto bt = sB_.Get<T>(); DMAin(bt, gG_, N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            ToF32<T>(gama_, bt, cB_, N_);
        }

        // --- y *= gamma ---
        AscendC::Mul(x_, x_, gama_, N_);

        // --- load beta → cB_ (beta_p, reusing cB_ area) ---
        {
            auto bt = sB_.Get<T>(); DMAin(bt, bg_, N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            ToF32<T>(beta_p, bt, cB_, N_);
        }
        AscendC::Add(x_, x_, beta_p, N_);  // y += beta

        // --- CopyOut y (x_ holds final result) ---
        auto yo = qY_.AllocTensor<T>();
        if constexpr (std::is_same_v<T, float>) {
            AscendC::Adds(yo.template ReinterpretCast<float>(), x_, 0.0f, N_);
        } else {
            AscendC::Cast(yo, x_, OutRnd<T>(), N_);
            AscendC::PipeBarrier<PIPE_V>();
        }
        qY_.EnQue(yo);

        yo = qY_.DeQue<T>(); DMAout(yG_[(uint64_t)ri*N_], yo, N_); qY_.FreeTensor(yo);

        // --- Write scalar outputs after main computation complete ---
        WriteOne<T>(mG_[ri], meanVal, pipe, cD_);
        WriteOne<T>(rG_[ri], rstdVal, pipe, cD_);
    }

private:
    int32_t M_=0, N_=0, bm_=0, ucn_=0, tpc_=0, sr_=0;
    float alp_=0.f, ep_=0.f, iN_=0.f;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<T> xG_, gxG_, gG_, bg_, mG_, rG_, yG_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sB_, rB_, sm_, cA_, cB_, cD_;
    AscendC::TQue<AscendC::TPosition::VECIN,BN>  qX_, qGX_;
    AscendC::TQue<AscendC::TPosition::VECOUT,BN> qY_;
    AscendC::LocalTensor<float> x_, gx_, c_, gama_, beta_p, r_, s_;
};

// ===== entry points (3 strategies, all delegate to same kernel) =====

template <typename T>
static __aicore__ inline void RunKernel(GM_ADDR xp, GM_ADDR gxp, GM_ADDR gp, GM_ADDR bep,
    GM_ADDR mp, GM_ADDR rp, GM_ADDR yp, int32_t M, int32_t N, int32_t bm, int32_t ucn, int32_t tpc,
    float alp, float ep, float iN) {
    DeepNormKernel<T> k;
    k.Init(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    k.Process();
}

extern "C" __global__ __aicore__ void deep_norm_merge_n(
    GM_ADDR xp, GM_ADDR gxp, GM_ADDR gp, GM_ADDR bep,
    GM_ADDR mp, GM_ADDR rp, GM_ADDR yp,
    int32_t M, int32_t N, int32_t bm, int32_t ucn,
    int32_t tpc, int32_t rowFactor, float alp, float ep, float iN, int64_t dtf) {
    (void)rowFactor;
    if (dtf==0) RunKernel<float>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    else if (dtf==1) RunKernel<half>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    else RunKernel<bfloat16_t>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
}
extern "C" __global__ __aicore__ void deep_norm_single_row(
    GM_ADDR xp, GM_ADDR gxp, GM_ADDR gp, GM_ADDR bep,
    GM_ADDR mp, GM_ADDR rp, GM_ADDR yp,
    int32_t M, int32_t N, int32_t bm, int32_t ucn,
    int32_t tpc, float alp, float ep, float iN, int64_t dtf) {
    if (dtf==0) RunKernel<float>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    else if (dtf==1) RunKernel<half>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    else RunKernel<bfloat16_t>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
}
extern "C" __global__ __aicore__ void deep_norm_splitd(
    GM_ADDR xp, GM_ADDR gxp, GM_ADDR gp, GM_ADDR bep,
    GM_ADDR mp, GM_ADDR rp, GM_ADDR yp,
    int32_t M, int32_t N, int32_t bm, int32_t ucn,
    int32_t tpc, float alp, float ep, float iN, int64_t dtf) {
    if (dtf==0) RunKernel<float>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    else if (dtf==1) RunKernel<half>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
    else RunKernel<bfloat16_t>(xp,gxp,gp,bep,mp,rp,yp,M,N,bm,ucn,tpc,alp,ep,iN);
}
