169	            auto bt = sB_.Get<T>(); DMAin(bt, gG_, N_);
170	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
171	            ToF32<T>(gama_, bt, cB2_, N_);
172	        }
173	
174	        // --- y *= gamma ---
175	        AscendC::Mul(x_, x_, gama_, N_);
176	
177	        // --- load beta → cB2_ ---
178	        {
179	            auto bt = sB_.Get<T>(); DMAin(bt, bg_, N_);
180	            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
181	            ToF32<T>(beta_p, bt, cB2_, N_);
182	        }
183	        AscendC::Add(x_, x_, beta_p, N_);  // y += beta
184	
185	        // --- CopyOut y (x_ holds final result) ---
186	        auto yo = qY_.AllocTensor<T>();
187	        if constexpr (std::is_same_v<T, float>) {
188	            AscendC::Adds(yo.template ReinterpretCast<float>(), x_, 0.0f, N_);
189	        } else {
190	            AscendC::Cast(yo, x_, OutRnd<T>(), N_);
191	            AscendC::PipeBarrier<PIPE_V>();
192	        }
193	        qY_.EnQue(yo);
194	
195	        yo = qY_.DeQue<T>(); DMAout(yG_[(uint64_t)ri*N_], yo, N_); qY_.FreeTensor(yo);
196	
197	        // --- Write scalar outputs after main computation complete ---
198	        WriteOne<T>(mG_[ri], meanVal, pipe, cD_);
199	        WriteOne<T>(rG_[ri], rstdVal, pipe, cD_);
200	    }
